script:
const titleEl = root_element.querySelector('.widget-title');
const loadingTextEl = root_element.querySelector('.loading-text');
const statusArea = root_element.querySelector('.gap-status-area');
const actionArea = root_element.querySelector('.gap-action-area');
const btn = root_element.querySelector('.btn-run-billing');

titleEl.innerText = __("Billing Continuity Monitor");
loadingTextEl.innerText = __("Checking ledger consistency...");
btn.innerText = __("Generate Missing Bills");

frappe.call({
    method: "qota.billing.utils.get_billing_gaps",
    callback: function(r) {
        if (!statusArea) return;
        if (r.message && r.message.length > 0) {
            window.last_detected_gaps = r.message;
            statusArea.innerHTML = `
                <p style="color: var(--red-500); margin: 0; font-size: 0.95em; font-weight: 600;">
                    ${__("Found {0} pending monthly cycles.").replace('{0}', '<b>' + r.message.length + '</b>')}
                </p>
                <small style="color: var(--text-muted);">${__("Missing debt records for open years.")}</small>
            `;
            if (actionArea) actionArea.style.display = 'block';
        } else {
            statusArea.innerHTML = `<p style="color: var(--green-500); margin: 0;"><i class="fa fa-check-circle"></i> ${__("All billed to date.")}</p>`;
        }
    }
});

if (btn) {
    btn.onclick = function() {
        const gaps = window.last_detected_gaps;
        if (!gaps || gaps.length === 0) return;

        // Crear el Diálogo
        let d = new frappe.ui.Dialog({
            title: __('Review Missing Bills'),
            fields: [{ fieldtype: 'HTML', fieldname: 'gaps_table' }],
            primary_action_label: __('Generate All'),
            primary_action(values) {
                d.hide();
                frappe.dom.freeze(__("Generating {0} Bills...").replace('{0}', gaps.length));
                
                frappe.call({
                    method: "qota.billing.utils.generate_bills_and_link_advances",
                    args: { gap_list: gaps },
                    callback: function(res) {
                        frappe.dom.unfreeze();
                        frappe.show_alert({message: __(res.message), indicator: 'green'});
                        setTimeout(() => { location.reload(); }, 1000);
                    }
                });
            }
        });

        // Construir la Tabla
        let rows = gaps.map(g => `
            <tr>
                <td><small>${g.contract}</small></td>
                <td><small>${g.full_name}</small></td>
                <td class="text-right"><span class="label label-warning">${__(g.month)} ${g.year}</span></td>
            </tr>
        `).join('');

        let table_html = `
            <div style="max-height: 400px; overflow-y: auto; border: 1px solid var(--border-color); border-radius: 4px;">
                <table class="table table-bordered table-hover table-condensed" style="margin: 0; font-size: 12px;">
                    <thead class="bg-light">
                        <tr>
                            <th>${__("Contract")}</th>
                            <th>${__("Subscriber")}</th>
                            <th class="text-right">${__("Period")}</th>
                        </tr>
                    </thead>
                    <tbody>${rows}</tbody>
                </table>
            </div>
            <div class="mt-2 text-right text-muted">
                <small>${__("Total items:")} <b>${gaps.length}</b></small>
            </div>
        `;

        d.get_field('gaps_table').$wrapper.html(table_html);
        d.show();
    };
}

style:
.billing-gap-card {
    margin: -7px !important;
    background-color: var(--card-bg);
    border: 1px solid var(--border-color);
    border-radius: var(--border-radius-md);
    padding: 16px;
    transition: background-color 0.2s ease, box-shadow 0.2s ease;
}

.billing-gap-card .widget-header {
    display: flex; 
    align-items: center; 
    margin-bottom: 12px;
}

.billing-gap-card .icon-container {
    /* Color de fondo suave que se adapta */
    background-color: var(--orange-100); 
    padding: 8px; 
    border-radius: var(--border-radius-sm);
    margin-right: 12px;
}

/* Ajuste para que el icono no brille demasiado en modo oscuro */
[data-theme="dark"] .billing-gap-card .icon-container {
    background-color: rgba(255, 152, 0, 0.15);
}

.billing-gap-card .icon-container i {
    color: var(--orange-600); 
    font-size: 1.2em;
}

.billing-gap-card .widget-title {
    margin: 0; 
    font-weight: 600;
    color: var(--text-color);
}

.billing-gap-card .text-muted-container {
    font-size: 0.9em;
    color: var(--text-muted);
}

.billing-gap-card .gap-action-area {
    display: none; 
    margin-top: 15px;
}

.billing-gap-card .btn-run-billing {
    width: 100%; 
    font-weight: 500;
    /* El botón btn-primary de Frappe ya cambia solo entre temas */
}
